package com.example.demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class DemoApplication {

    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }
}

package com.example.demo;

import org.springframework.stereotype.Service;

@Service
public class GreetingService {

    private final MessageRepository messageRepository;

    public GreetingService(MessageRepository messageRepository) {
        this.messageRepository = messageRepository;
    }

    public String greet(String name) {
        String template = messageRepository.findTemplate();
        return "%s, %s!".formatted(template, name);
    }
}

package com.example.demo;

public interface MessageRepository {

    String findTemplate();
}

package com.example.demo;

import org.springframework.stereotype.Repository;

@Repository
public class DefaultMessageRepository implements MessageRepository {

    @Override
    public String findTemplate() {
        return "Hello";
    }
}

package com.example.demo;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
class DemoApplicationTests {

    @Autowired
    private GreetingService greetingService;

    @Test
    void contextLoads() {
        assertThat(greetingService).isNotNull();
    }

    @Test
    void greetingUsesRepositoryTemplate() {
        assertThat(greetingService.greet("World")).isEqualTo("Hello, World!");
    }
}

package com.example.demo;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.verify;

@ExtendWith(MockitoExtension.class)
class GreetingServiceTest {

    @Mock
    private MessageRepository messageRepository;

    @InjectMocks
    private GreetingService greetingService;

    @Test
    void greetBuildsMessageFromRepositoryTemplate() {
        given(messageRepository.findTemplate()).willReturn("Hi");

        String result = greetingService.greet("Alice");

        assertThat(result).isEqualTo("Hi, Alice!");
        verify(messageRepository).findTemplate();
    }
}
